insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$pedagio$q$, $q$municipais$q$, $q$https://www.lamsa.com.br/www.lamsa.com.br/pages/pedagio.html + https://www.viario.com.br/tarifas-do-pedagio.php + https://www.crpconcessionaria.com.br/ (tabelas transcritas em data/raw/pedagio/concessoes_estaduais.json)$q$, $q$Tabelas publicadas pelas concessionárias por obrigação legal (Lei 8.987/1995, art. 9º, §5º): só os valores, com citação; sites sem licença aberta (LAMSA: "todos os direitos reservados"). Posição: OpenStreetMap (ODbL 1.0)$q$, 4, $q$Tabelas transcritas em 2026-10-10. rio_linha_amarela: 1 ponto(s), ativo; rio_transolimpica: 2 ponto(s), ativo; mg_crp_pirapetinga: 1 ponto(s), INATIVO (situação jurídica incerta: cobrança suspensa por decisão judicial em ação do MPMG (notícia de 13/10/2025), mas o site da CRP e o OSM (check_date 2026-05-13) indicam cobrança)$q$);
